import{_ as t,o as a,c as n,ah as s}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Panel interne edPage","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"admission/staff-edpage/index.md","filePath":"src/admission/staff-edpage/index.md"}'),i={name:"admission/staff-edpage/index.md"};function l(r,e,o,u,c,d){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="panel-interne-edpage" tabindex="-1">Panel interne edPage <a class="header-anchor" href="#panel-interne-edpage" aria-label="Permalink to &quot;Panel interne edPage&quot;">​</a></h1><p>Le panel interne Era Admission est l&#39;outil réservé à l&#39;équipe edPage pour gérer le cycle de vie des établissements inscrits en ligne : accorder une licence, clore une démonstration avant terme, ou purger un établissement expiré. Il n&#39;a aucun rapport avec un compte utilisateur d&#39;un établissement client — c&#39;est un accès entièrement séparé.</p><h2 id="se-connecter-au-panel" tabindex="-1">Se connecter au panel <a class="header-anchor" href="#se-connecter-au-panel" aria-label="Permalink to &quot;Se connecter au panel&quot;">​</a></h2><ol><li>Rendez-vous sur la page de connexion staff, accessible sur le domaine central d&#39;ERA (celui du site d&#39;inscription, pas le sous-domaine d&#39;un établissement).</li><li>Saisissez votre adresse e-mail et votre mot de passe <strong>de compte staff</strong> — ce compte est indépendant de tout compte d&#39;établissement, il n&#39;existe que pour l&#39;équipe edPage.</li><li>Validez. Vous arrivez sur la liste des établissements.</li></ol><p>Le formulaire de connexion staff est volontairement limité (pas d&#39;inscription libre, pas de double authentification, pas de réinitialisation de mot de passe en self-service) : les comptes staff sont créés à la main, pas via un flux public.</p><h2 id="consulter-la-liste-des-etablissements" tabindex="-1">Consulter la liste des établissements <a class="header-anchor" href="#consulter-la-liste-des-etablissements" aria-label="Permalink to &quot;Consulter la liste des établissements&quot;">​</a></h2><p>Une fois connecté, la page « Établissements » liste tous les établissements inscrits, avec pour chacun :</p><ul><li>son nom et son sous-domaine ;</li><li>son <strong>statut</strong> : gratuit, démo, licencié ou expiré ;</li><li>ses <strong>pôles</strong> actifs (aucun en gratuit ; tous en démo ; ceux effectivement licenciés en licencié ; aucun en expiré) ;</li><li>sa <strong>formule d&#39;hébergement</strong> (autonome ou clé en main) ;</li><li>la date de fin de démo, la date jusqu&#39;à laquelle la maintenance est payée, et depuis quand l&#39;établissement est expiré, selon ce qui s&#39;applique.</li></ul><p>Chaque ligne propose ensuite les actions disponibles pour cet établissement, décrites ci-dessous — certaines n&#39;apparaissent que pour certains statuts.</p><h2 id="accorder-une-licence" tabindex="-1">Accorder une licence <a class="header-anchor" href="#accorder-une-licence" aria-label="Permalink to &quot;Accorder une licence&quot;">​</a></h2><p>Disponible pour tout établissement, quel que soit son statut actuel.</p><ol><li>Sur la ligne de l&#39;établissement concerné, cliquez sur <strong>Licencier</strong>.</li><li>Dans la boîte de dialogue, cochez les pôles à accorder (ou l&#39;option « Offre complète » pour tous les pôles d&#39;un coup). Le tarif de chaque pôle est rappelé à côté de son nom.</li><li>Renseignez, si besoin, la date jusqu&#39;à laquelle la maintenance est payée. Laissée vide, elle est fixée automatiquement à un an à partir d&#39;aujourd&#39;hui.</li><li>Confirmez avec <strong>Octroyer la licence</strong>.</li></ol><p>L&#39;établissement passe immédiatement au statut « Licencié », avec les pôles cochés actifs, tout en restant hébergé sur l&#39;infrastructure edPage (formule « Clé en main »). Si l&#39;établissement doit finalement héberger lui-même son installation (formule « Autonome »), la bascule se fait par un outil en ligne de commande dédié, hors de ce panel — n&#39;utilisez pas cette action pour ce cas-là.</p><p>Cette action peut aussi être utilisée pour <strong>modifier</strong> la licence d&#39;un établissement déjà licencié (ajouter un pôle, prolonger la maintenance) : il suffit de la réappliquer avec les nouvelles valeurs.</p><h2 id="cloturer-une-demonstration-manuellement" tabindex="-1">Clôturer une démonstration manuellement <a class="header-anchor" href="#cloturer-une-demonstration-manuellement" aria-label="Permalink to &quot;Clôturer une démonstration manuellement&quot;">​</a></h2><p>Disponible uniquement pour un établissement au statut « Démo ». L&#39;action n&#39;apparaît pas sur les autres statuts.</p><ol><li>Sur la ligne de l&#39;établissement, cliquez sur <strong>Terminer la démo</strong>.</li><li>Confirmez dans la boîte de dialogue — l&#39;action est immédiate.</li></ol><p>L&#39;établissement passe au statut « Expiré » et repasse en lecture seule, exactement comme si sa démo s&#39;était terminée naturellement à l&#39;échéance prévue. Utilisez cette action pour mettre fin à une démo avant son terme normal (par exemple à la demande de l&#39;établissement, ou en cas d&#39;usage abusif) — ce n&#39;est pas nécessaire dans le cours normal des choses, la démo se termine d&#39;elle-même.</p><h2 id="purger-un-etablissement-expire" tabindex="-1">Purger un établissement expiré <a class="header-anchor" href="#purger-un-etablissement-expire" aria-label="Permalink to &quot;Purger un établissement expiré&quot;">​</a></h2><p>Disponible uniquement pour un établissement au statut « Expiré ». Cette action est <strong>définitive et irréversible</strong>.</p><ol><li>Sur la ligne de l&#39;établissement, cliquez sur <strong>Purger</strong>.</li><li>Relisez attentivement le message d&#39;avertissement dans la boîte de dialogue : il rappelle que l&#39;établissement, sa base de données et son stockage seront supprimés immédiatement, sans délai de grâce ni possibilité d&#39;annulation.</li><li>Confirmez avec <strong>Supprimer définitivement</strong>.</li></ol><p>Dans le cours normal des choses, un établissement expiré depuis trop longtemps est purgé automatiquement à l&#39;issue de son délai de grâce. Utilisez cette action manuelle uniquement pour purger un établissement avant l&#39;échéance automatique — par exemple à la demande explicite de l&#39;établissement de supprimer ses données sans attendre.</p>',22)])])}const g=t(i,[["render",l]]);export{p as __pageData,g as default};
